import { MathDocumentPage } from '../../types/mathDocuments';

interface DownloadViewOnlyMarkdownArgs {
    documentTitle: string;
    documentDescription?: string;
    pages: MathDocumentPage[];
    /** Keep "## Page N" headings and --- separators between pages. Default true. */
    includePageSeparators?: boolean;
    /** Prepend a note that the file was generated by AI conversion. Default true. */
    includeAiDisclaimer?: boolean;
}

const sanitizeFileName = (value: string) => {
    const sanitized = value
        .trim()
        .replace(/[<>:"/\\|?*\x00-\x1f]/g, '')
        .replace(/\s+/g, ' ')
        .slice(0, 80)
        .trim();

    return sanitized || 'math-document';
};

const AI_DISCLAIMER =
    '> *This document was generated by feeding page images into an AI model. ' +
    'Content may contain transcription errors — please verify against the original pages.*';

export const downloadViewOnlyMarkdown = ({
    documentTitle,
    documentDescription,
    pages,
    includePageSeparators = true,
    includeAiDisclaimer = true,
}: DownloadViewOnlyMarkdownArgs) => {
    if (typeof window === 'undefined') {
        return;
    }

    const title = documentTitle?.trim() || 'Math document';
    const sections: string[] = [];

    if (includeAiDisclaimer) {
        sections.push(AI_DISCLAIMER);
    }

    sections.push(`# ${title}`);

    if (documentDescription?.trim()) {
        sections.push(documentDescription.trim());
    }

    let markdownContent: string;
    if (includePageSeparators) {
        pages.forEach((page) => {
            const pageHeading = `## Page ${page.pageNumber}${page.title?.trim() ? `: ${page.title.trim()}` : ''}`;
            const pageMarkdown = page.markdown?.trim() || '_No markdown content for this page._';
            sections.push(`${pageHeading}\n\n${pageMarkdown}`);
        });
        markdownContent = sections.join('\n\n---\n\n') + '\n';
    } else {
        const body = pages.map((page) => page.markdown?.trim() || '_No markdown content for this page._');
        markdownContent = [...sections, ...body].join('\n\n') + '\n';
    }

    const blob = new Blob([markdownContent], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);

    const anchor = window.document.createElement('a');
    anchor.href = url;
    anchor.download = `${sanitizeFileName(title)}.md`;
    window.document.body.appendChild(anchor);
    anchor.click();
    window.document.body.removeChild(anchor);

    window.setTimeout(() => URL.revokeObjectURL(url), 0);
};
